p=Path(sys.argv[1]);cold=json.loads((p/'confirmation/analysis.json').read_text());gate=json.loads((p/'confirmation/cold-confirmation-gate.json').read_text());combined=json.loads((p/'combined/analysis.json').read_text())if(p/'combined/analysis.json').exists()else None
esc=lambda v:html.escape(str(v));num=lambda x:f'{x:+.2f}';ci=lambda x:f'{num(x[0])} to {num(x[1])}'
