c=cold['primaryContrasts'][0];old=cold['previousColdScreenSeparate'];sections=[]
sections.append('<p class="eyebrow">CENTURY • MODIFICATION EVALUATION • NOVEMBER 14, 2026</p><h1>Cold confirmation & combined modifiers</h1>')
sections.append('<div class="decision"><strong>'+('The adverse cold effect was confirmed.'if gate['confirmed']else'The adverse cold effect was not confirmed by the fixed gate.')+'</strong> Fresh-seed paired winner change: '+num(c['winChangePoints'])+' percentage points; conservative 95% interval '+ci(c['winInterval'])+'. '+('The authorized combined screen followed automatically.'if combined else'The dependent combined screen did not run.')+'</div>')
sections.append('<p>All values describe this laboratory engine and eight copied clubs in four fixed pairings. Thermal moderation 0.35 and the reduced shared psychology policy remain provisional. No official results, player ratings, roster/tactical inputs, deployed engine or default coefficients were changed.</p>')
sections.append('<h2>Fresh cold result compared with the earlier screen</h2>')
sections.append(table(['Study','Matched seeds','Adverse minus mean tolerance','95% interval','Paired margin change'],[['Earlier severe-cold screen',old['n'],num(old['winChangePoints'])+' pp',ci(old['winInterval'])+' pp',num(old['scoreMargin']['mean'])],['Fresh confirmation',c['n'],num(c['winChangePoints'])+' pp',ci(c['winInterval'])+' pp',num(c['scoreMargin']['mean'])]]))
sections.append('<p>These studies were analyzed separately, without pooling. Both compare opposed extreme cold tolerance (focal 0, opponent 1) against mean tolerance in the same −5°C wet/windy conditions. The fresh confirmation contains '+str(c['changedToFocal'])+' winner changes toward the focal club and '+str(c['changedAgainstFocal'])+' against it. Directional replication confirms a model effect; it does not establish that its magnitude is acceptable.</p>')
if c['winInterval'][0]<-8:sections.append('<p class="flag">Cold review flag: the fresh interval still includes an adverse effect larger than the provisional eight-point review level. Confirmation is not a coefficient acceptance decision.</p>')
else:sections.append('<p>The fresh pooled interval stays within the provisional eight-point adverse review level for these fixed pairings. That does not certify every pairing, all conditions or a global ceiling, and does not establish that the true effect changed from the earlier screen.</p>')
sections.append(table(['Cold copied pairing','Adverse win change','Four-profile protected 95% interval'],[[b['focal']+' vs '+b['opponent'],num(b['contrasts'][0]['overall']['winChangePoints'])+' pp',ci(b['contrasts'][0]['overall']['winInterval'])+' pp']for b in cold['matchups']]))
sections.append(table(['Focal simulation side','Cold win change','Exploratory nominal 95% interval'],[[int(v['swap']),num(v['contrasts'][0]['winChangePoints'])+' pp',ci(v['contrasts'][0]['winInterval'])+' pp']for v in cold['primarySides']]))
sections.append('<p>All four cold pairing point estimates and both side-specific estimates are adverse. The individual pairing intervals are wider than the pooled interval and still extend beyond the eight-point review reference; the pooled finding does not certify each pairing. Side comparisons are exploratory.</p>')
sections.append('<h2>Audit and continuation gate</h2><p>All '+format(cold['outcomes'],',')+' retained full outcomes passed gzip/CRC, saved-input reconstruction, SHA-256, scoring, statistics and clock checks. The declared compact analyses were independently recomputed. The gate required the fresh primary interval’s upper endpoint below zero and all verification checks to pass; it was fixed before new outcomes. Neutral parity, both sides, save/resume, source boundaries and shared-cap behavior were qualified before execution.</p>')
if combined:
 sections.append('<h2>Combined corner screen</h2><p>Each corner uses 1,024 fresh matched seeds and is compared with its own neutral dry-18°C control. Intervals below protect the primary family of four comparisons. This is an initial interaction screen, not a high-precision ceiling certification.</p>')
 rows=[]
 for v in combined['primaryContrasts']:
  arm=v['contrast'].split(' minus ')[0];rows.append([arm.replace('-',' '),f"{combined['cells'][arm]['focalWinRatePct']:.2f}%",num(v['winChangePoints'])+' pp',ci(v['winInterval'])+' pp',num(v['scoreMargin']['mean']),f"{v['changedToFocal']} / {v['changedAgainstFocal']}"])
 sections.append(table(['Corner','Focal win rate','Change vs control','Family-protected 95% interval','Margin change','Winner changes for / against'],rows))
 sections.append('<p>Neutral focal win rate: '+f"{combined['cells']['control']['focalWinRatePct']:.2f}%"+'. Hot = 35°C / 80% humidity; cold = −5°C / 90%. Both use 35/50 km/h wind/gusts, 5 mm/h rain and 45° direction. Thermal tolerance is opposed at 0 and 1 with moderation 0.35; the other tolerance is held at 0.5. Favorable psychology gives the focal club five wins, the opponent five losses and focal home support; adverse reverses those assignments. Confidence scale is 0.20, home odds bonus 0.004, shared positive odds cap 0.006; frustration scale stays 1.</p>')
 flags=[]
 for v in combined['primaryContrasts']:
  arm=v['contrast'].split(' minus ')[0];extent=max(abs(x)for x in v['winInterval'])
  if extent>10:flags.append(arm+' interval extends beyond '+('15'if extent>15 else'10')+' pp')
 sections.append('<p class="flag">Review: '+esc('; '.join(flags)if flags else'All four intervals remain within the provisional ±10-point reference band in these specified corners.')+'. Review references are not certified global ceilings.</p>')
 sections.append('<h2>Added psychology and interactions</h2>')
 add=[v for v in combined['secondaryContrasts']if '-combined-'in v['contrast']]
 sections.append(table(['Same physical conditions; add psychology','Win change','Nominal 95% interval','Margin change'],[[v['contrast'].split(' minus ')[0].replace('-',' '),num(v['winChangePoints'])+' pp',ci(v['winInterval'])+' pp',num(v['scoreMargin']['mean'])]for v in add]))
 sections.append('<p>The difference-of-differences below is combined − physical-only − psychology-only + control on the same seeds. Its winner contrast can range from −2 to +2, so it uses a paired normal interval rather than a two-arm discordance interval.</p>')
 sections.append(table(['Interaction','Winner interaction','Nominal 95% interval','Margin interaction'],[[v['environment']+' '+v['direction'],num(v['values']['winChangePoints']['mean'])+' pp',ci(v['values']['winChangePoints']['interval'])+' pp',num(v['values']['scoreMargin']['mean'])]for v in combined['interactions']]))
 interactions_clear=[v['environment']+' '+v['direction']for v in combined['interactions']if not(v['values']['winChangePoints']['interval'][0]<=0<=v['values']['winChangePoints']['interval'][1])]
 sections.append('<p>'+('Exploratory winner interaction intervals exclude zero for: '+esc(', '.join(interactions_clear))+'. These are nominal secondary comparisons.'if interactions_clear else'All four exploratory winner interaction intervals include zero. That does not establish additivity; the screen leaves substantial interaction uncertainty.')+'</p>')
 sections.append('<h2>All arms: physical and disciplinary diagnostics</h2>')
 rows=[]
 for arm,v in combined['cells'].items():
  t=combined['disciplineAndPsychology'][arm];f=t['focal'];o=t['opponent']
  rows.append([arm,f"{v['focalWinRatePct']:.2f}%",f"{v['meanMinutes']:.2f}",f"{100*v['clubs']['focal']['activeEnergy']:.2f} / {100*v['clubs']['opponent']['activeEnergy']:.2f}",f"{f['fouls']} / {o['fouls']}",f"{f['seriousFouls']} / {o['seriousFouls']}",f"{f['seriousPctOfFouls']:.2f}% / {o['seriousPctOfFouls']:.2f}%",f"{f['capSaturationPct']:.1f}% / {o['capSaturationPct']:.1f}%"])
 sections.append(table(['Arm','Win rate','Minutes','Active energy 0–100, focal / opponent','Fouls','Serious fouls','Serious / fouls','Psychology cap saturation'],rows))
 sections.append('<p>Active energy is weighted by active-player time separately for each club. Serious-foul rates use each club’s observed fouls as denominator; contact counts, fouls per 100 contacts, requested extra fatigue, final energy, shots/minute and psychology components are included in analysis.json. A shared odds cap limits direct per-action input, not the eventual match win-rate effect.</p>')
 sections.append('<h2>Pairing and side sensitivity</h2>')
 rows=[]
 for b in combined['matchups']:
  for v in b['contrasts'][:4]:
   q=v['overall'];rows.append([b['focal']+' vs '+b['opponent'],q['contrast'].split(' minus ')[0],num(q['winChangePoints'])+' pp',ci(q['winInterval'])+' pp'])
 sections.append(table(['Copied pairing','Corner','Win change','Exploratory nominal 95% interval'],rows))
 sections.append('<p>Each pairing contributes 256 seeds split evenly between simulation sides. Complete side-specific and profile-specific comparisons remain in the machine-readable analysis; pooled direction consistently follows the designated focal intervention. Profile and side findings are exploratory and are not selected as preferred results.</p>')
sections.append('<h2>Decision and next evaluation</h2><p>'+('Retain the current coefficients as laboratory candidates. Prioritize a fresh-seed precision confirmation of the hot favored combined corner: its observed lift is 11.52 percentage points and its family-protected interval reaches 18.54 points. Its absolute focal win rate is 59.86% against a 48.34% neutral control. This does not indicate invincibility in the tested fixtures, but the total-effect uncertainty is too broad to certify the intended modifier budget. Hold coefficients and inputs fixed while defining the next confirmation criterion. The four exploratory interaction intervals include zero; extra amplification from stacking was not established, and meaningful interaction remains possible.'if combined else'The fixed continuation condition was not met. Preserve this result and review the cold mechanism and uncertainty before defining another study; no automatic sample expansion or reroll was performed.')+'</p><p>Scope limits: four specific weather/tolerance/psychology corners, eight healthy copied clubs, original tactics, fixed date and quarter-end policy. The combined screen has no same-weather mean-tolerance arm, so weather and thermal-tolerance contributions cannot be separated there. It does not cover all weather directions or severities, all league matchups, season histories, availability effects or halftime adaptation. Halftime adaptation remains unimplemented. No global invincibility or ceiling conclusion follows from these data.</p>')
sections.append('<h2>Reproduction and retained evidence</h2><p>The package includes the fixed plan, exact profiles and manifests, source patch and commit pins, all compact paired outcomes with weather/lab telemetry, per-ledger SHA-256 index, full-ledger audit proofs, independent recomputation proofs and continuation gate. The large full event ledgers stay separate from this compact deliverable. Apply reproduction/source.patch to the pinned base commit, install the repository’s locked dependencies, then follow reproduction/README.txt. No prior outcomes are pooled into either fresh study.</p>')
fig,axes=plt.subplots(1,2 if combined else 1,figsize=(13 if combined else 7,4.5),squeeze=False);ax=axes[0,0]
for i,(label,v)in enumerate([('Earlier cold screen',old),('Fresh cold confirmation',c)]):
 x=v['winChangePoints'];lo,hi=v['winInterval'];ax.errorbar(x,i,xerr=[[x-lo],[hi-x]],fmt='o',capsize=5,color='#24638b');ax.text(hi+.3,i,f'{x:+.2f}',va='center',fontsize=9)
ax.set_yticks([0,1],['Earlier screen\nn=2,048','Fresh confirmation\nn=10,240']);ax.set_title('Adverse cold vs mean tolerance');ax.axvline(0,color='#75808a',lw=1);ax.axvline(-8,color='#bd722e',ls=':',lw=1);ax.set_xlabel('Win-rate change (percentage points)');ax.grid(axis='x',alpha=.2)
if combined:
 ax=axes[0,1]
 for i,v in enumerate(combined['primaryContrasts']):
  x=v['winChangePoints'];lo,hi=v['winInterval'];color='#267651'if'favored'in v['contrast']else'#ac4444';ax.errorbar(x,i,xerr=[[x-lo],[hi-x]],fmt='o',capsize=5,color=color)
 ax.set_yticks(range(4),[v['contrast'].split(' minus ')[0].replace('-combined-',' / ')for v in combined['primaryContrasts']]);ax.set_title('Combined corners vs neutral control\nFamily-protected conservative 95% intervals');ax.axvline(0,color='#75808a',lw=1);ax.axvspan(-10,10,color='#267651',alpha=.045);ax.set_xlabel('Win-rate change (percentage points)');ax.grid(axis='x',alpha=.2)
fig.tight_layout();fig.savefig(p/'effect-comparison.png',dpi=180,bbox_inches='tight');fig.savefig(p/'effect-comparison.svg',bbox_inches='tight');plt.close(fig)
